Consider a supervised learning framework in a regression setting, with a given training dataset $\mathcal{D} \coloneqq \left\{\left(\bm{x}_{\mathcal{D}, i}, \bm{y}_{\mathcal{D}, i}\right)\right\}_{i = 1}^k$, i.e.,
\begin{equation*}
    \bm{x}_{\mathcal{D}} \coloneqq \sum_{i = 1}^k \bm{x}_{\mathcal{D}, i} \otimes \bm{e}_i \in \mathbb{R}^{d_{\mathrm{in}} \times k} \quad \text{and} \quad
    \bm{y}_{\mathcal{D}} \coloneqq \sum_{i = 1}^k \bm{y}_{\mathcal{D}, i} \otimes \bm{e}_i \in \mathbb{R}^{d_{\mathrm{out}} \times k}.
\end{equation*}

\label{def:nn}
   A fully connected feed-forward NN is defined through an architecture $\bm{\alpha} \coloneqq (\bm{n}, \bm{\varphi})$ with:
   \begin{enumerate}
       \item $\bm{n}$ denoting the sizes of the $L + 1$ layers\footnote{An input layer, $L - 1$ hidden layers and an output layer.} (with $L \geq 2$)
       \begin{equation*}
           \bm{n} \coloneqq \big(n_0 (\eqcolon d_{\mathrm{in}}), n_1, \dots, n_{L - 1}, n_L (\eqcolon d_{\mathrm{out}})\big), \, n_l \in \mathbb{N}_{> 0}, \, \forall\,\,\,\, l = 0, \dots, L;
       \end{equation*}		
       \item $\bm{\varphi}$ denoting the $L$ activation functions (applied component-wise)
       \begin{equation*}
           \bm{\varphi} \coloneqq (\varphi_1, \dots, \varphi_L), \, \varphi_l: \mathbb{R} \to \mathbb{R}, \, \forall\,\,\,\, l \in [L], \text{ with } \varphi_1(x) = x, \forall\,\,\,\, x \in \mathbb{R}.
       \end{equation*}
   \end{enumerate}
   In particular, $\forall\,\,\,\, \bm{x}_0 \in \mathbb{R}^{d_{\mathrm{in}}}$, the NN is defined as $f(\bm{x}_0) \coloneqq f^{(L)}(\bm{x}_0)$ with


   \begin{equation} \label{eq:nn}
       \begin{aligned}
           & f^{(l)}: \mathbb{R}^{d_{\mathrm{in}}} \to \mathbb{R}^{n_l}, \ \forall\,\,\,\, l = 0, \dots, L, \\
           & f^{(0)}(\bm{x}_0) = \bm{x}_0, \quad f^{(l)}(\bm{x}_0) = \bm{W}^{(l)} \varphi_l\left(f^{(l - 1)}(\bm{x}_0)\right) + \bm{b}^{(l)} \text{ for } l \in [L], \\
       \end{aligned}
   \end{equation}
   where, for any $l \in [L]$, $\bm{W}^{(l)} \in \mathbb{R}^{n_l \times n_{l - 1}}$ and $\bm{b}^{(l)} \in \mathbb{R}^{n_l}$ denote weight matrices and bias vectors, respectively.

\begin{equation*}
            \bm{n} \coloneqq \big(n_0 (\eqcolon d_{\mathrm{in}}), n_1, \dots, n_{L - 1}, n_L (\eqcolon d_{\mathrm{out}})\big), \, n_l \in \mathbb{N}_{> 0}, \, \forall\,\,\,\, l = 0, \dots, L;
        \end{equation*}

\begin{equation} \label{eq:nn}
        \begin{aligned}
            & f^{(l)}: \mathbb{R}^{d_{\mathrm{in}}} \to \mathbb{R}^{n_l}, \ \forall\,\,\,\, l = 0, \dots, L, \\
            & f^{(0)}(\bm{x}_0) = \bm{x}_0, \quad f^{(l)}(\bm{x}_0) = \bm{W}^{(l)} \varphi_l\left(f^{(l - 1)}(\bm{x}_0)\right) + \bm{b}^{(l)} \text{ for } l \in [L], \\
        \end{aligned}
    \end{equation}

Bayes' theorem, and a related notion of posterior measure, can be naturally built without the necessity of density functions.
Let $\bm{\theta}: (\Omega, \mathcal{A}, \mathbb{P}) \to \mathbb{R}^S$ random variable, $S$ finite set, and an evidence $\mathcal{D}$ with density $\mathcal{L}(\bm{\theta}; \bm{y}_{\mathcal{D}})$, we define the posterior measure of $\bm{\theta}$ as
\begin{equation} \label{eq:bayesbnnmeasure}
    \mathbb{P}_{\bm{\theta} | \mathcal{D}} \coloneqq \frac{\mathcal{L}(\cdot; \bm{y}_{\mathcal{D}})}{\int_{\mathbb{R}^S} \mathcal{L}(\bm{\theta}; \bm{y}_{\mathcal{D}}) d\mathbb{P}_{\bm{\theta}}(\bm{\theta})} \mathbb{P}_{\bm{\theta}},
\end{equation}
where, given $\nu$ measure on $(\mathbb{R}^S, \borel{\mathbb{R}^S})$ ($S$ finite set), and $f: \mathbb{R}^S \to \mathbb{R}$, we use the notation $f \nu$ to denote the measure on $(\mathbb{R}^S, \borel{\mathbb{R}^S})$ absolutely continuous with respect to $\nu$ ($f \nu \ll \nu$), with density $f$, i.e., $\forall\,\,\,\, A \in \borel{\mathbb{R}^S}$, $f \nu (A) = \int_{A} f(\bm{u}) d\nu(\bm{u})$. For the sake of simplicity we always work with densities (as in \cref{eq:bayesbnn}) if they are available, and we swap to the measure theoretic definition in \cref{eq:bayesbnnmeasure} otherwise.

Specifically, given the vector of variances $\bm{\sigma} \coloneqq \smash{\big(\big(\sigma_{\bm{W}^{(l)}}^2, \sigma_{\bm{b}^{(l)}}^2\big)\big)_{l = 1}^{L}} \in \left(\mathbb{R}^+ \times \mathbb{R}^+\right)^L$, we assume that
\begin{equation} \label{eq:nealprior}
    \begin{gathered}
        \bm{W}^{(l)} \sim \normal{\bm{0}_{n_l \times n_{l - 1}}}{\sigma_{\bm{W}^{(l)}}^2 / n_{l - 1} \, \bm{I}_{n_l \times n_{l - 1}}}, \ 
        \bm{b}^{(l)} \sim \normal{\bm{0}_{n_l}}{\sigma_{\bm{b}^{(l)}}^2 \bm{I}_{n_l}}, \text{ for } l \in [L].
    \end{gathered}
\end{equation}

\label{rem:nncompact}
   In order to have a simpler description of the subsequent theory it is convenient to write the layers of the BNNs in a compact form: $f^{(0)}_{\bm{\theta}}: \mathbb{R}^{d_{\mathrm{in}} \times m} \to \mathbb{R}^{d_{\mathrm{in}} \times m}$, $f^{(0)}_{\bm{\theta}}(\bm{x}) = \bm{x}$ and for every $l \in [L]$, $f^{(l)}_{\bm{\theta}}: \mathbb{R}^{n_{l - 1} \times m} \to \mathbb{R}^{n_l \times m}$,
   \begin{align*}
       f^{(l)}_{\bm{\theta}}(\bm{x}) & = \sum_{i = 1}^m f^{(l)}_{\bm{\theta}}(\bm{x}_i) \otimes \bm{e}_i = \sum_{i = 1}^m \bm{W}^{(l)} \varphi_l\left(f^{(l - 1)}_{\bm{\theta}}(\bm{x}_i)\right) \otimes \bm{e}_i + \bm{b}^{(l)} \otimes \bm{1}_{m} = \\
       & = \left(\bm{W}^{(l)} \otimes \bm{I}_{m}\right) \varphi_l\left(f^{(l - 1)}_{\bm{\theta}}(\bm{x})\right) + \bm{b}^{(l)} \otimes \bm{1}_{m},
   \end{align*}
   where $\bm{W}^{(l)} \otimes \bm{I}_{m} \in \mathbb{R}^{(n_l \times n_{l - 1}) \times (m \times m)}$ should be thought as an element of $\mathbb{R}^{(n_l \times m) \times (n_{l - 1} \times m)}$. We define $f_{\bm{\theta}}(\bm{x}) \coloneqq f^{(L)}_{\bm{\theta}}(\bm{x})$.

\label{def:gp}
   Let $H = (H(\bm{x}_0))_{\bm{x}_0 \in \mathbb{R}^{d_{\mathrm{in}}}}$ be a stochastic process such that for any $\bm{x}_0 \in \mathbb{R}^{d_{\mathrm{in}}}$, $H(\bm{x}_0)$ is a random vector with values in $\left(\mathbb{R}^{d_{\mathrm{out}}}, \borel{\mathbb{R}^{d_{\mathrm{out}}}}\right)$. 
   Then $H$ is said to be a Gaussian process with mean function $\bm{M}: \mathbb{R}^{d_{\mathrm{in}}} \to \mathbb{R}^{d_{\mathrm{out}}}$ and covariance kernel $\bm{H}: \mathbb{R}^{d_{\mathrm{in}}} \times \mathbb{R}^{d_{\mathrm{in}}} \to \mathbb{R}^{d_{\mathrm{out}} \times d_{\mathrm{out}}}$, if for any $m > 0$, given $\bm{x} = (\bm{x}_i)_{i = 1}^m \in \mathbb{R}^{d_{\mathrm{in}} \times m}$,
   \begin{equation*}
       H(\bm{x}) \coloneqq \left(H(\bm{x}_1), \dots, H(\bm{x}_m)\right) \sim \normal{\bm{M}(\bm{x})}{\bm{H}(\bm{x})},
   \end{equation*}
   where
   \begin{equation*}
       \bm{M}(\bm{x}) = \left(\bm{M}(\bm{x}_1), \dots, \bm{M}(\bm{x}_m)\right) \in \mathbb{R}^{d_{\mathrm{out}} \times m},
   \end{equation*}
   and $\bm{H}(\bm{x}) \in \mathbb{R}^{(d_{\mathrm{out}} \times m) \times (d_{\mathrm{out}} \times m)}$ can be viewed as a block matrix with $m \times m$ blocks such that, for any $i, j \in [m]^2$, the block $(i, j)$ of $\bm{H}(\bm{x})$ is $\left(\bm{H}(\bm{x})\right)_{i, j} = \bm{H}(\bm{x}_i, \bm{x}_j) \in \mathbb{R}^{d_{\mathrm{out}} \times d_{\mathrm{out}}}$. 
   For such $H$ we set $H \sim \mathcal{GP}\left(\bm{M}, \bm{H}\right)$.

\begin{equation} \label{eq:nngpx}	
    \begin{aligned}
        & G^{(0)}(\bm{x}) \coloneqq \bm{x} \in \mathbb{R}^{d_{\mathrm{in}} \times m} \text{ constant r.v.}, \\
        & G^{(l)}(\bm{x}) \sim \normal{\bm{0}_{n_l \times m}}{\bm{I}_{n_l} \otimes \bm{K}^{(l)}(\bm{x})}, \text{ with } \bm{K}^{(l)}(\bm{x}) \coloneqq \left(\bm{K}^{(l)}(\bm{x}_i, \bm{x}_j)\right)_{i, j \in [m] \times [m]},
    \end{aligned}
\end{equation}

\label{thm:priornngp}


   Let $f_{\bm{\theta}}$ BNN, with architecture $\bm{\alpha} = (\bm{n}, \bm{\varphi})$, $\bm{\varphi}$ collection of Lipschitz activation functions, a prior on $\bm{\theta}$ as in \cref{eq:nealprior}, $\left(G^{(l)}\right)_{l = 1}^L$ Gaussian processes as in \cref{eq:nngp} and an input set $\bm{x} \in \mathbb{R}^{d_{\mathrm{in} \times m}}$. Then, $\forall\,\,\,\, l \in [L]$ exists a constant $c > 0$ independent of $\left(n_j\right)_{j = 1}^l$, such that,
   \begin{equation} \label{eq:priornngp}
       \wass[p]{f_{\bm{\theta}}^{(l)}(\bm{x})}{G^{(l)}(\bm{x})} \leq c \sqrt{n_l} \sum_{j = 1}^{l - 1} \frac{1}{\sqrt{n_j}}.
   \end{equation}

\label{rem:gaussposterior}
   An immediate consequence of \Cref{thm:priornngp} (achievable applying \Cref{thm:wassdist}) is that, by letting $n_l$ grow to $\infty$, the process $f^{(l)}_{\bm{\theta}}$ associated with the $l$-th hidden layer of a BNN evaluated on $\bm{x}$ converges in distribution to the NNGP's component $G^{(l)}(\bm{x})$: given $n_{min} \coloneqq \min_{j = 1, \dots, l - 1} n_j$,
   \begin{equation*}
       f^{(l)}_{\bm{\theta}}(\bm{x}) \xrightarrow[n_{min} \to \infty]{law} \normal{\bm{0}_{n_l \times m}}{\bm{I}_{n_l} \otimes \bm{K}^{(l)}(\bm{x})}.
   \end{equation*} 
   Therefore, \Cref{thm:priornngp} yields a quantitative version of what has already been proved by \citet{matthews2018,lee2018}.

In particular, by assuming
\begin{equation} \label{eq:hiervariancenngp}
    \begin{gathered}	
        \sigma_{\bm{W}^{(l)}}^2, \sigma_{\bm{b}^{(l)}}^2 \text{ constants, } \forall\,\,\,\, l = 1, \dots, L - 1, \\
        \sigma^2 \coloneqq \sigma_{\bm{W}^{(L)}}^2 = \sigma_{\bm{b}^{(L)}}^2 = \sigma_{\scalebox{0.65}{$\kern-3pt\bm{y}_{\mathcal{D}}$}}^2 \quad \text{and} \quad \sigma^2 \sim \invgamma{a}{b}, \text{ with } a, b > 0,
    \end{gathered}
\end{equation}
we have
\begin{equation} \label{eq:hiermodel}
    \begin{aligned}
        G(\bm{x}_{\mathcal{D}}) \, | \, \sigma^2 & \sim \normal{\bm{0}_{n_L \times k}}{\sigma^2 \bm{I}_{n_L} \otimes \bm{K}'(\bm{x}_{\mathcal{D}})}, \\
        \sigma^2 & \sim \invgamma{a}{b}, \text{ Inverse-Gamma with } a, b > 0, \\
        \bm{y}_{\mathcal{D}} \, | \, G(\bm{x}_{\mathcal{D}}), \sigma^2 & \sim \normal{G(\bm{x}_{\mathcal{D}})}{\sigma^2 \bm{I}_{n_L \times k}},
    \end{aligned}
\end{equation}
with
\begin{align} \label{eq:rescaledkernel}
    \bm{K}'(\bm{x}_{\mathcal{D}}) = \mean{\varphi_{L}\left(G^{(L - 1)}(\bm{x}_{\mathcal{D}})\right)^T \varphi_{L}\left(G^{(L - 1)}(\bm{x}_{\mathcal{D}})\right)} / n_L + \bm{1}_{k \times k},
\end{align}
rescaled NNGP kernel independent of $\sigma^2$. Therefore, observing that
\begin{equation*}
    p_{G(\bm{x}_{\mathcal{D}}), \sigma^2 | \mathcal{D}}(\bm{z}, \sigma^2) \propto p_{\bm{y}_{\mathcal{D}} | G(\bm{x}_{\mathcal{D}}), \sigma^2}(\bm{y}_{\mathcal{D}}) \, p_{G(\bm{x}_{\mathcal{D}}) | \sigma^2}(\bm{z}) \, p_{\sigma^2}(\sigma^2),
\end{equation*}
assuming $\bm{K}'(\bm{x}_{\mathcal{D}})$ to be invertible, $n_L = 1$, and applying standard tricks (see \Cref{sec:postnngp}), we obtain that
\begin{equation*}
    \begin{aligned}
        G(\bm{x}_{\mathcal{D}}) \, | \, \sigma^2, \mathcal{D} & \sim \normal{\bm{y}_{\mathcal{D}} \bm{M}^{-1}}{\sigma^2 \bm{M}^{-1}}, \\
        \sigma^{2} \, | \, \mathcal{D} & \sim \invgamma{a + \frac{k}{2}}{b + \frac{1}{2} \left(\bm{y}_{\mathcal{D}} \left(\bm{I}_{k} - \bm{M}^{-1}\right) (\bm{y}_{\mathcal{D}})^T\right)}.
    \end{aligned}
\end{equation*}
Hence,
\begin{equation*}
    \begin{aligned}
        G(\bm{x}_{\mathcal{D}}) \, | \, \mathcal{D} \sim \tstud{2a + k}{\bm{\mu}_{\mathrm{post}}}{\bm{\Sigma}_{\mathrm{post}}},
    \end{aligned}
\end{equation*}
with
\begin{equation} \label{eq:tstudpostparams}
    \begin{aligned}
        \bm{M} & \coloneqq \bm{I}_{k} + \bm{K}'(\bm{x}_{\mathcal{D}})^{-1}, \\
        \bm{\mu}_{\mathrm{post}} & \coloneqq \bm{y}_{\mathcal{D}} \bm{M}^{-1}, \\
        \bm{\Sigma}_{\mathrm{post}} & \coloneqq \left(b + \frac{1}{2} \left(\bm{y}_{\mathcal{D}} \left(\bm{I}_{k} - \bm{M}^{-1}\right) (\bm{y}_{\mathcal{D}})^T\right)\right) \frac{2}{2a + k} \bm{M}^{-1}.
    \end{aligned}
\end{equation}

\begin{equation} \label{eq:hiervariancenngp}
