        \sigma_{\bm{W}^{(l)}}^2, \sigma_{\bm{b}^{(l)}}^2 \text{ constants, } \forall\,\,\,\, l = 1, \dots, L - 1, \\
        \sigma^2 \coloneqq \sigma_{\bm{W}^{(L)}}^2 = \sigma_{\bm{b}^{(L)}}^2 = \sigma_{\scalebox{0.65}{$\kern-3pt\bm{y}_{\mathcal{D}}$}}^2 \quad \text{and} \quad \sigma^2 \sim \invgamma{a}{b}, \text{ with } a, b > 0,
    \end{gathered}
\end{equation}

\begin{equation} \label{eq:hiermodel}
    \begin{aligned}
        G(\bm{x}_{\mathcal{D}}) \, | \, \sigma^2 & \sim \normal{\bm{0}_{n_L \times k}}{\sigma^2 \bm{I}_{n_L} \otimes \bm{K}'(\bm{x}_{\mathcal{D}})}, \\
        \sigma^2 & \sim \invgamma{a}{b}, \text{ Inverse-Gamma with } a, b > 0, \\
        \bm{y}_{\mathcal{D}} \, | \, G(\bm{x}_{\mathcal{D}}), \sigma^2 & \sim \normal{G(\bm{x}_{\mathcal{D}})}{\sigma^2 \bm{I}_{n_L \times k}},
