\label{rem:poststudtprocess}
   In a completely analogous way, it is possible to show that, given an input test set $\bm{x}_{\mathcal{T}} \in \mathbb{R}^{n_0 \times k'}$, 
   \begin{equation} \label{eq:poststudtprocess}
       \begin{aligned}
           & G(\bm{x}_{\mathcal{T}}) \, | \, \mathcal{D} \sim \tstud{2a + k}{\bm{\mu}'_{\mathrm{post}}}{\left(b + \frac{1}{2} \left(\bm{y}_{\mathcal{D}} \left(\bm{I}_{k} - \bm{M}^{-1}\right) (\bm{y}_{\mathcal{D}})^T\right)\right) \frac{2}{2a + k} \bm{\Sigma}'_{\mathrm{post}}}, \text{ with } \\
           & \kern20pt \bm{\mu}'_{\mathrm{post}} \coloneqq \bm{K}'(\bm{x}_{\mathcal{T}}, \bm{x}_{\mathcal{D}}) \left(\bm{K}'(\bm{x}_{\mathcal{D}}) + \sigma^2 I_{k}\right)^{-1} \bm{y}_{\mathcal{D}}, \\
           & \kern20pt \bm{\Sigma}'_{\mathrm{post}} \coloneqq \bm{K}'(\bm{x}_{\mathcal{T}}) - \bm{K}'(\bm{x}_{\mathcal{T}}, \bm{x}_{\mathcal{D}}) \left(\bm{K}'(\bm{x}_{\mathcal{D}}) + \sigma^2 I_{k}\right)^{-1} \bm{K}'(\bm{x}_{\mathcal{T}}, \bm{x}_{\mathcal{D}}). \\
       \end{aligned}
   \end{equation}
   Indeed, following the strategy adopted by \citet[eqs. (2.22) to (2.24)]{gp2006}, we can observe that
   \begin{align*}
       & G(\bm{x}_{\mathcal{T}}) \, | \, \sigma^2, \mathcal{D} \sim \normal{\bm{\mu}'_{\mathrm{post}}}{\bm{\Sigma}'_{\mathrm{post}}}, \\
       & \sigma^2 \, | \, \mathcal{D} \sim \invgamma{a + \frac{k}{2}}{b + \frac{1}{2} \left(\bm{y}_{\mathcal{D}} \left(\bm{I}_{k} - \bm{M}^{-1}\right) (\bm{y}_{\mathcal{D}})^T\right)},
   \end{align*}
   which in turn implies \cref{eq:poststudtprocess} by means of \Cref{lem:norminvgammastudent}.

\begin{equation} \label{eq:poststudtprocess}
        \begin{aligned}
            & G(\bm{x}_{\mathcal{T}}) \, | \, \mathcal{D} \sim \tstud{2a + k}{\bm{\mu}'_{\mathrm{post}}}{\left(b + \frac{1}{2} \left(\bm{y}_{\mathcal{D}} \left(\bm{I}_{k} - \bm{M}^{-1}\right) (\bm{y}_{\mathcal{D}})^T\right)\right) \frac{2}{2a + k} \bm{\Sigma}'_{\mathrm{post}}}, \text{ with } \\
            & \kern20pt \bm{\mu}'_{\mathrm{post}} \coloneqq \bm{K}'(\bm{x}_{\mathcal{T}}, \bm{x}_{\mathcal{D}}) \left(\bm{K}'(\bm{x}_{\mathcal{D}}) + \sigma^2 I_{k}\right)^{-1} \bm{y}_{\mathcal{D}}, \\
            & \kern20pt \bm{\Sigma}'_{\mathrm{post}} \coloneqq \bm{K}'(\bm{x}_{\mathcal{T}}) - \bm{K}'(\bm{x}_{\mathcal{T}}, \bm{x}_{\mathcal{D}}) \left(\bm{K}'(\bm{x}_{\mathcal{D}}) + \sigma^2 I_{k}\right)^{-1} \bm{K}'(\bm{x}_{\mathcal{T}}, \bm{x}_{\mathcal{D}}). \\
        \end{aligned}
    \end{equation}

We define $\widetilde{\mu} \sim f_{\bm{\theta}}(\bm{x})$, $\mu \sim G(\bm{x})$, with $\bm{x} = (\bm{x}_{\mathcal{D}}, \bm{x}_{\mathcal{T}}) \in \mathbb{R}^{n_0 \times (k + k')}$, fixed input set which extends the input training set with a possible input test set, and omit the dependence on $\bm{y}_{\mathcal{D}}$ in the Gaussian likelihood $\mathcal{L}$\footnote{Now $\mathcal{L}$ depends also on $s \coloneqq \sigma^2$, which is no more a parameter.}, where
\begin{equation} \label{eq:likelihood}
    \mathcal{L}: \mathbb{R}^{n_L \times k} \times \mathbb{R}^{+} \to \mathbb{R}, \ \mathcal{L}(\bm{z}, s) = \frac{1}{\left(2 \pi s\right)^{n_L k / 2}} \exp{-\frac{1}{2 s} \norm{\bm{y}_{\mathcal{D}} - \bm{z}}_F^2}.
\end{equation}

\label{def:postnngpbnn}
   Given a BNN as in \Cref{def:bnn}, we assume to have a hierarchical model as the one described in \cref{eq:hiermodel} for the NNGP, and an analogous model for the BNN (i.e., Gaussian prior on $\bm{\theta}$ as in \cref{eq:nealprior}, prior on the variance $\sigma^2$ as in \cref{eq:hiervariancenngp} and a likelihood as in \cref{eq:likelihood}). Then, for any $A \in \borel{\mathbb{R}^{n_L \times k}}$, we define the posterior measures as follows: given $\mu \sim G(\bm{x})$ and $\widetilde{\mu} \sim f_{\bm{\theta}}(\bm{x})$,
   \begin{equation*}
       \begin{aligned}
           & \mu_{\mathrm{post}}(A) \coloneqq \int_A \int_{\mathbb{R}^+} \frac{1}{\mathit{I}} \mathcal{L}(\bm{z}, s) p_{\sigma^2}(s) ds \mu(d\bm{z}), \ \mathit{I} \coloneqq \int_{\mathbb{R}^{n_L \times k}} \int_{\mathbb{R}^+} \mathcal{L}(\bm{z}, s) p_{\sigma^2}(s) ds \mu(d\bm{z}), \\
           & \widetilde{\mu}_{\mathrm{post}}(A) \coloneqq \int_A \int_{\mathbb{R}^+} \frac{1}{\widetilde{\mathit{I}}} \mathcal{L}(\bm{z}, s) p_{\sigma^2}(s) ds \widetilde{\mu}(d\bm{z}), \ \widetilde{\mathit{I}} \coloneqq \int_{\mathbb{R}^{n_L \times k}} \int_{\mathbb{R}^+} \mathcal{L}(\bm{z}, s) p_{\sigma^2}(s) ds \widetilde{\mu}(d\bm{z}).
       \end{aligned}
   \end{equation*}

\begin{equation*}
        \begin{aligned}
            & \mu_{\mathrm{post}}(A) \coloneqq \int_A \int_{\mathbb{R}^+} \frac{1}{\mathit{I}} \mathcal{L}(\bm{z}, s) p_{\sigma^2}(s) ds \mu(d\bm{z}), \ \mathit{I} \coloneqq \int_{\mathbb{R}^{n_L \times k}} \int_{\mathbb{R}^+} \mathcal{L}(\bm{z}, s) p_{\sigma^2}(s) ds \mu(d\bm{z}), \\
            & \widetilde{\mu}_{\mathrm{post}}(A) \coloneqq \int_A \int_{\mathbb{R}^+} \frac{1}{\widetilde{\mathit{I}}} \mathcal{L}(\bm{z}, s) p_{\sigma^2}(s) ds \widetilde{\mu}(d\bm{z}), \ \widetilde{\mathit{I}} \coloneqq \int_{\mathbb{R}^{n_L \times k}} \int_{\mathbb{R}^+} \mathcal{L}(\bm{z}, s) p_{\sigma^2}(s) ds \widetilde{\mu}(d\bm{z}).
        \end{aligned}
    \end{equation*}

\label{thm:studposterior}
   Let $f_{\bm{\theta}}$, $G$, $\bm{x}$ and $\bm{y}_{\mathcal{D}}$ as above, $\mathcal{L}$ density of a $\normal{\bm{z}}{\sigma_{\scalebox{0.65}{$\kern-3pt\bm{y}_{\mathcal{D}}$}}^2 \bm{I}_{n_L \times k}}$. Assume a common variance for the last hidden layer of the BNN and the likelihood, distributed as an Inverse-Gamma 
   \begin{equation*}
       \sigma^2 \coloneqq \sigma_{\bm{W}^{(L)}}^2 = \sigma_{\bm{b}^{(L)}}^2 = \sigma_{\scalebox{0.65}{$\kern-3pt\bm{y}_{\mathcal{D}}$}}^2, \ \sigma^2 \sim \invgamma{a}{b},
   \end{equation*}
   with
   \begin{equation} \label{eq:abconstr}
       a > \frac{1}{2}, \ b > \left(1 + \frac{\varepsilon + 2}{2\varepsilon + 2}\right) \norm{\bm{y}_{\mathcal{D}}}_F^2, \text{ for any } \varepsilon < 1/\norm{\bm{K}'(\bm{x})}_{\mathrm{op}}. 
   \end{equation}
   Then, there exists a constant $c > 0$, independent of $\left(n_l\right)_{l = 1}^{L - 1}$, such that
   \begin{equation*}
       \wass[1]{f_{\bm{\theta}}(\bm{x}) \, | \, \mathcal{D}}{G(\bm{x}) \, | \, \mathcal{D}} \leq \frac{c}{\sqrt{n_{min}}}.
   \end{equation*}




The idea is to show the convergence of $f_{\bm{\theta}}(\bm{x}) \, | \, \mathcal{D}$ to $G(\bm{x}) \, | \, \mathcal{D}$ through the following steps: 
\begin{enumerate}
    \item partially retracing the strategy introduced by \citet{trevisan2023}, we first prove that there exist some constants $c > 0$ independent of $\left(n_l\right)_{l = 1}^{L - 1}$ and $\sigma^2$, and a function $h: \mathbb{R}^+ \to \mathbb{R}^+$ independent on $\left(n_l\right)_{l = 1}^{L - 1}$ as well, such that
    \begin{equation} \label{eq:simpleconvposteriorsigma}
        \wass[1]{f_{\bm{\theta}}(\bm{x}) \, | \, (\mathcal{D}, \sigma^2)}{G(\bm{x}) \, | \, (\mathcal{D}, \sigma^2)} \leq h(\sigma^2) \frac{c_0}{\sqrt{n_{min}}};
    \end{equation}


    \item we try to apply the convexity property of $1$-Wasserstein distance in the following \Cref{prop:wassconvexity} (\hyperlink{proof:wassconvexity}{proof} in \Cref{subsec:wassdist}) to the families of probabilities $\left(\mathbb{P}_{f_{\bm{\theta}}(\bm{x}) \, | \, (\mathcal{D}, \sigma^2)}\right)_{\sigma^2 \in \mathbb{R}^+}$ and $\left(\mathbb{P}_{G(\bm{x}) \, | \, (\mathcal{D}, \sigma^2)}\right)_{\sigma^2 \in \mathbb{R}^+}$, which would lead to the thesis.
    \begin{proposition} \label{prop:wassconvexity}
        Let us consider two Markov kernels $(\mu(s))_{s \in \mathbb{R}^+}$, $(\widetilde{\mu}(s))_{s \in \mathbb{R}^+}$ with source $\mathbb{R}^+$ and target $\mathbb{R}^T$ and a measure $\nu$ on $\mathbb{R}^+$ ($T$ finite set).
        Defining the probability measures on $\mathbb{R}^T$ such that, $\forall\,\,\,\, B \in \borel{\mathbb{R}^T}$,
        \begin{equation*}
            \mu(B) \coloneqq \int_{\mathbb{R}^+} \mu(s)(B) d\nu(s), \quad \widetilde{\mu}(B) \coloneqq \int_{\mathbb{R}^+} \widetilde{\mu}(s)(B) d\nu(s),
        \end{equation*}
        the following convexity property for the distance $\mathcal{W}_1$ holds: 
        \begin{equation} \label{eq:wassconvex}
            \wass[1]{\mu}{\widetilde{\mu}} \leq \int_{\mathbb{R}^+} \wass[1]{\mu(s)}{\widetilde{\mu}(s)} d\nu(s).
        \end{equation}
    \end{proposition}
\end{enumerate}
Unfortunately the second step is not easy as it could seem since \Cref{prop:wassconvexity} requires two families of probability measures (in particular Markov kernels) integrated with respect to the same measure $\nu$, which is not exactly our setting. 
Let us describe the issue before approaching the solution. For this purpose it is useful to introduce
\begin{equation*}
    \begin{aligned}
        \mathit{I}_{\sigma^2}(s) \coloneqq \int_{\mathbb{R}^{n_L \times k}} \mathcal{L}(\bm{z}, s) \mu(d\bm{z}), \quad \widetilde{\mathit{I}}_{\sigma^2}(s) \coloneqq \int_{\mathbb{R}^{n_L \times k}} \mathcal{L}(\bm{z}, s) \widetilde{\mu}(d\bm{z}),
    \end{aligned}
\end{equation*}
which allow us to write, $\forall\,\,\,\, A \in \borel{\mathbb{R}^{n_L \times k}}$,
\begin{equation} \label{eq:mupost}
    \begin{aligned}
        & \mu_{\mathrm{post}}(A) = \int_{\mathbb{R}^+} \mu_{\sigma^2}(s)(A) \frac{\mathit{I}_{\sigma^2}(s)}{\mathit{I}} p_{\sigma^2}(s) ds, \text{ with } \mu_{\sigma^2}(s)(A) \coloneqq \int_A \frac{\mathcal{L}(\bm{z}, s) \mu(d\bm{z})}{\mathit{I}_{\sigma^2}(s)}, \\
        & \widetilde{\mu}_{\mathrm{post}}(A) = \int_{\mathbb{R}^+} \widetilde{\mu}_{\sigma^2}(s)(A) \frac{\widetilde{\mathit{I}}_{\sigma^2}(s)}{\widetilde{\mathit{I}}} p_{\sigma^2}(s) ds, \text{ with } \widetilde{\mu}_{\sigma^2}(s)(A) \coloneqq \int_A \frac{\mathcal{L}(\bm{z}, s) \widetilde{\mu}(d\bm{z})}{\widetilde{\mathit{I}}_{\sigma^2}(s)}.
    \end{aligned}
\end{equation}
Eventually, we can note that the two families $(\mu_{\sigma^2}(s))_{s \in \mathbb{R}^+}$ and $(\widetilde{\mu}_{\sigma^2}(s))_{s \in \mathbb{R}^S}$, which coincide respectively with $\left(\mathbb{P}_{G(\bm{x}) \, | \, (\mathcal{D}, \sigma^2)}\right)_{\sigma^2 \in \mathbb{R}^+}$ and $\left(\mathbb{P}_{f_{\bm{\theta}}(\bm{x}) \, | \, (\mathcal{D}, \sigma^2)}\right)_{\sigma^2 \in \mathbb{R}^+}$, are integrated with respect to different measures.
Hence, it is clear that to apply \cref{eq:wassconvex} it is necessary to use the triangle inequality,
\begin{equation} \label{eq:trianstep}
    \wass[1]{\mu_{\mathrm{post}}}{\widetilde{\mu}_{\mathrm{post}}} \leq \wass[1]{\mu_{\mathrm{post}}}{\bar{\mu}} + \wass[1]{\bar{\mu}}{\widetilde{\mu}_{\mathrm{post}}},
\end{equation}
where we inserted a third measure,
\begin{equation} \label{eq:barmu}
    \bar{\mu}(A) \coloneqq \int_{\mathbb{R}^+} \widetilde{\mu}_{\sigma^2}(s)(A) \frac{\mathit{I}_{\sigma^2}(s)}{\mathit{I}} p_{\sigma^2}(s) ds, \ \forall\,\,\,\, A \in \borel{\mathbb{R}^{n_L \times k}},
\end{equation}
specifically constructed to satisfy the hypothesis of the convexity property. \\
Now, to conclude, we just need to control both the terms on the right-hand side of \cref{eq:trianstep}.
\begin{itemize}[leftmargin = 2.5cm]
    \item[\textit{1\textsuperscript{st} term.}] We just apply the aforementioned convexity property getting
    \begin{equation*}
        \wass[1]{\mu_{\mathrm{post}}}{\bar{\mu}} \leq \int_{\mathbb{R}^+} \wass[1]{\mu_{\sigma^2}(s)}{\widetilde{\mu}_{\sigma^2}(s)} \frac{\mathit{I}_{\sigma^2}(s)}{\mathit{I}} p_{\sigma^2}(s) ds.
    \end{equation*}
    Therefore by \cref{eq:simpleconvposteriorsigma} we get 
    \begin{equation*}
        \wass[1]{\mu_{\mathrm{post}}}{\bar{\mu}} \leq \frac{c_0}{\sqrt{n_{min}}} \int_{\mathbb{R}^+} h(s) \frac{\mathit{I}_{\sigma^2}(s)}{\mathit{I}} p_{\sigma^2}(s) ds \leq \frac{c_1}{\sqrt{n_{min}}},
    \end{equation*}
    where, in order to bound the last integral it is necessary to introduce a constraint on $a$ and $b$, as in \cref{eq:abconstr}.
    \item[\textit{2\textsuperscript{nd} term.}] We exploit the following technical \Cref{lem:boundwasstv}, in combination with several bounds on the first moments of the considered probability measures.


    \begin{lemma} \label{lem:boundwasstv}
        Let $\mu$, $\nu$ be measures on $\mathbb{R}^S$, then, denoting with $|\mu - \nu|$ the total variation measure, it holds
        \begin{equation*}
            \wass[1]{\mu}{\nu} \leq \int_{\mathbb{R}^S} \norm{\bm{u}} d |\mu - \nu|(\bm{u}).
        \end{equation*}
    \end{lemma}
\end{itemize}
