We first rewrite the map in a more compact form in terms of the Frobenius norm of $(\bm{y}_{\mathcal{D}} - \bm{z})$: $\forall\,\,\,\, \bm{z} \in \mathbb{R}^{n_L \times k}$,
\begin{equation*}
	\mathcal{L}(\bm{z}; \bm{y}_{\mathcal{D}}) = \frac{1}{\left(2 \pi \sigma_{\scalebox{0.65}{$\kern-3pt\bm{y}_{\mathcal{D}}$}}^2\right)^{n_L k / 2}} \exp{-\frac{1}{2\sigma_{\scalebox{0.65}{$\kern-3pt\bm{y}_{\mathcal{D}}$}}^2} \norm{\bm{y}_{\mathcal{D}} - \bm{z}}_F^2}.
\end{equation*}
Then for the uniform norm it is sufficient to recall that $\mathcal{L}$ is a bell-shaped map with maximum in the mean point. 
Therefore, it is immediate that
\begin{equation*}
	\norm{\mathcal{L}}_{\infty} = \mathcal{L}(\bm{y}_{\mathcal{D}}; \bm{y}_{\mathcal{D}}) = \frac{1}{\left(2 \pi \sigma_{\scalebox{0.65}{$\kern-3pt\bm{y}_{\mathcal{D}}$}}^2\right)^{n_L k / 2}}.
\end{equation*}
For the identification of the Lipschitz constant it is necessary to recall that, as a consequence of the Mean Value Theorem, given a map $g: \Omega \to \mathbb{R}$ with $\Omega$ open convex subset of $\mathbb{R}^S$, $S$ finite set, if $\sup_{\bm{z} \in \Omega} \norm{\partial / \partial \bm{z} \, g(\bm{z})} \leq L$, then $\mathcal{L}$ is $L$-Lipschitz.
Hence, our objective is to identify the value of $\sup_{\bm{z} \in \mathbb{R}^{n_L \times k}} \norm{\partial / \partial \bm{z} \, \mathcal{L}(\bm{z}; \bm{y}_{\mathcal{D}})}_F$. \\
Let us define $c = \frac{1}{\left(2 \pi \sigma_{\scalebox{0.65}{$\kern-3pt\bm{y}_{\mathcal{D}}$}}^2\right)^{n_L k / 2}}$, then
\begin{equation*}


	\begin{aligned}
		\frac{\partial}{\partial \bm{z}} \mathcal{L}(\bm{z}; \bm{y}_{\mathcal{D}}) & = c \, \frac{\partial}{\partial \bm{z}} \exp{-\frac{1}{2\sigma_{\scalebox{0.65}{$\kern-3pt\bm{y}_{\mathcal{D}}$}}^2} \norm{\bm{y}_{\mathcal{D}} - \bm{z}}_F^2} = \\
		& = c \, \frac{\partial}{\partial \norm{\bm{y}_{\mathcal{D}} - \bm{z}}_F^2} \exp{-\frac{1}{2\sigma_{\scalebox{0.65}{$\kern-3pt\bm{y}_{\mathcal{D}}$}}^2} \norm{\bm{y}_{\mathcal{D}} - \bm{z}}_F^2} \frac{\partial}{\partial (\bm{y}_{\mathcal{D}} - \bm{z})} \norm{\bm{y}_{\mathcal{D}} - \bm{z}}_F^2 \frac{\partial}{\partial \bm{z}} (\bm{y}_{\mathcal{D}} - \bm{z}) = \\
		& = c \, \left(- \frac{1}{2 \sigma_{\scalebox{0.65}{$\kern-3pt\bm{y}_{\mathcal{D}}$}}^2} \exp{-\frac{1}{2\sigma_{\scalebox{0.65}{$\kern-3pt\bm{y}_{\mathcal{D}}$}}^2} \norm{\bm{y}_{\mathcal{D}} - \bm{z}}_F^2}\right) 2 (\bm{y}_{\mathcal{D}} - \bm{z}) \left(- \bm{I}_{n_L \times k}\right) = \frac{\bm{y}_{\mathcal{D}} - \bm{z}}{\sigma_{\scalebox{0.65}{$\kern-3pt\bm{y}_{\mathcal{D}}$}}^2} \mathcal{L}(\bm{z}; \bm{y}_{\mathcal{D}}).
	\end{aligned}
\end{equation*}
To find the supremum of $h: \mathbb{R}^{n_L \times k} \to \mathbb{R}$, 
\begin{equation*}
	h(\bm{z}) \coloneqq \norm{\frac{\partial}{\partial \bm{z}} \mathcal{L}(\bm{z}; \bm{y}_{\mathcal{D}})}_F = \frac{\norm{\bm{y}_{\mathcal{D}} - \bm{z}}_F}{\sigma_{\scalebox{0.65}{$\kern-3pt\bm{y}_{\mathcal{D}}$}}^2} \mathcal{L}(\bm{z}; \bm{y}_{\mathcal{D}}), \ \forall\,\,\,\, \bm{z} \in \mathbb{R}^{n_L \times k},
\end{equation*}
we first have to notice that $h$ is a positive real valued map, and that its first derivative has zeros in every $\bm{z}_0$ such that $\norm{\bm{y}_{\mathcal{D}} - \bm{z}_0}_F^2 = \sigma_{\scalebox{0.65}{$\kern-3pt\bm{y}_{\mathcal{D}}$}}^2$, which, as a consequence, are critical points. Indeed, for every $\bm{z} \neq \bm{y}_{\mathcal{D}}$,
\begin{align*}
	\frac{\partial}{\partial \bm{z}} h(\bm{z}) & = \frac{1}{\sigma_{\scalebox{0.65}{$\kern-3pt\bm{y}_{\mathcal{D}}$}}^2} \left(\frac{\partial}{\partial \bm{z}} \mathcal{L}(\bm{z}; \bm{y}_{\mathcal{D}}) \norm{\bm{y}_{\mathcal{D}} - \bm{z}}_F + \mathcal{L}(\bm{z}; \bm{y}_{\mathcal{D}}) \frac{\partial}{\partial \bm{z}} \norm{\bm{y}_{\mathcal{D}} - \bm{z}}_F\right) = \\
	& = \frac{1}{\sigma_{\scalebox{0.65}{$\kern-3pt\bm{y}_{\mathcal{D}}$}}^2} \left(\frac{\bm{y}_{\mathcal{D}} - \bm{z}}{\sigma_{\scalebox{0.65}{$\kern-3pt\bm{y}_{\mathcal{D}}$}}^2} \mathcal{L}(\bm{z}; \bm{y}_{\mathcal{D}}) \norm{\bm{y}_{\mathcal{D}} - \bm{z}}_F - \mathcal{L}(\bm{z}; \bm{y}_{\mathcal{D}}) \frac{\bm{y}_{\mathcal{D}} - \bm{z}}{\norm{\bm{y}_{\mathcal{D}} - \bm{z}}_F}\right) = \\
	& = \frac{1}{\sigma_{\scalebox{0.65}{$\kern-3pt\bm{y}_{\mathcal{D}}$}}^2} \mathcal{L}(\bm{z}; \bm{y}_{\mathcal{D}}) \frac{\bm{y}_{\mathcal{D}} - \bm{z}}{\norm{\bm{y}_{\mathcal{D}} - \bm{z}}_F} \left(\frac{\norm{\bm{y}_{\mathcal{D}} - \bm{z}}_F^2}{\sigma_{\scalebox{0.65}{$\kern-3pt\bm{y}_{\mathcal{D}}$}}^2} - 1\right),
\end{align*}
which is null if and only if $\norm{\bm{y}_{\mathcal{D}} - \bm{z}}_F^2 / \sigma_{\scalebox{0.65}{$\kern-3pt\bm{y}_{\mathcal{D}}$}}^2 = 1$. \\
For any such $\bm{z}_0$ we would have that
\begin{equation*}
	h(\bm{z}_0) = \mathcal{L}\left(\bm{z}_0; \bm{y}_{\mathcal{D}}\right) = \frac{1}{\sqrt{\sigma_{\scalebox{0.65}{$\kern-3pt\bm{y}_{\mathcal{D}}$}}^2}} \frac{e^{-1/2}}{\left(2 \pi \sigma_{\scalebox{0.65}{$\kern-3pt\bm{y}_{\mathcal{D}}$}}^2\right)^{n_L k / 2}}.
\end{equation*}
It is also possible to define 
\begin{equation*}
	l: \mathbb{R}^+ \to \mathbb{R}, \ l(x) \coloneqq \frac{x}{\sigma_{\scalebox{0.65}{$\kern-3pt\bm{y}_{\mathcal{D}}$}}^2} \frac{1}{\left(2 \pi \sigma_{\scalebox{0.65}{$\kern-3pt\bm{y}_{\mathcal{D}}$}}^2\right)^{n_L k / 2}} \exp{-\frac{1}{2 \sigma_{\scalebox{0.65}{$\kern-3pt\bm{y}_{\mathcal{D}}$}}^2} x^2}, \ \forall\,\,\,\, x \in \mathbb{R}^+,
\end{equation*}
which, by construction, has the following property: 
\begin{equation*}
	\forall\,\,\,\, \bm{z} \in \mathbb{R}^{n_L \times k}, \ l(\norm{\bm{y}_{\mathcal{D}} - \bm{z}}_F) = h(\bm{z}).
\end{equation*}
From the definition it is easy to see that $\sup_{x \in \mathbb{R}^+} l(x) = h(\bm{z}_0)$, just computing its first two derivatives $l'$ and $l''$. Defining $d = \sigma_{\scalebox{0.65}{$\kern-3pt\bm{y}_{\mathcal{D}}$}}^{-2} \left(2 \pi \sigma_{\scalebox{0.65}{$\kern-3pt\bm{y}_{\mathcal{D}}$}}^2\right)^{- n_L k / 2}$ positive constant we have
\begin{align*}
	l'(x) & = d \exp{-\frac{1}{2\sigma_{\scalebox{0.65}{$\kern-3pt\bm{y}_{\mathcal{D}}$}}^2} x^2} \left(1 - x^2 \frac{1}{\sigma_{\scalebox{0.65}{$\kern-3pt\bm{y}_{\mathcal{D}}$}}^2}\right), \\
	l''(x) & = - d \exp{-\frac{1}{2\sigma_{\scalebox{0.65}{$\kern-3pt\bm{y}_{\mathcal{D}}$}}^2} x^2} \frac{1}{\sigma_{\scalebox{0.65}{$\kern-3pt\bm{y}_{\mathcal{D}}$}}^2} x \left(\left(1 - x^2 \frac{1}{\sigma_{\scalebox{0.65}{$\kern-3pt\bm{y}_{\mathcal{D}}$}}^2}\right) + 2\right) = \\
	& = - d \exp{-\frac{1}{2\sigma_{\scalebox{0.65}{$\kern-3pt\bm{y}_{\mathcal{D}}$}}^2} x^2} \frac{1}{\sigma_{\scalebox{0.65}{$\kern-3pt\bm{y}_{\mathcal{D}}$}}^2} x \left(3 - \frac{x^2}{\sigma_{\scalebox{0.65}{$\kern-3pt\bm{y}_{\mathcal{D}}$}}^2}\right),
\end{align*}
and so
\begin{align*}
	l'(x) = 0 \iff x^2 = \sigma_{\scalebox{0.65}{$\kern-3pt\bm{y}_{\mathcal{D}}$}}^2, \ l''(x) \leq 0 \iff x^2 \leq 3 \sigma_{\scalebox{0.65}{$\kern-3pt\bm{y}_{\mathcal{D}}$}}^2.
\end{align*}
This implies that in $x = \sqrt{\sigma_{\scalebox{0.65}{$\kern-3pt\bm{y}_{\mathcal{D}}$}}^2}$ there is a local maximum and observing the asymptotic behavior, $\lim_{x \to +\infty} l(x) = 0$, we know that it is the unique global maximum. 
Finally, evaluating $l$ in $\sqrt{\sigma_{\scalebox{0.65}{$\kern-3pt\bm{y}_{\mathcal{D}}$}}^2}$ we get 
\begin{equation*}
	l\left(\sqrt{\sigma_{\scalebox{0.65}{$\kern-3pt\bm{y}_{\mathcal{D}}$}}^2}\right) = \frac{1}{\sqrt{\sigma_{\scalebox{0.65}{$\kern-3pt\bm{y}_{\mathcal{D}}$}}^2}} \frac{e^{- 1/2}}{\left(2 \pi \sigma_{\scalebox{0.65}{$\kern-3pt\bm{y}_{\mathcal{D}}$}}^2\right)^{n_L k / 2}}.
\end{equation*}
Therefore, it follows that the critical points $\bm{z}_0$ are global maxima for $h$ and so
\begin{equation*}
	\sup_{\bm{z} \in \mathbb{R}^{n_L \times k}} \norm{\frac{\partial}{\partial \bm{z}} \mathcal{L}(\bm{z}; \bm{y}_{\mathcal{D}})}_F = h(\bm{z}_0).
\end{equation*}

\begin{align*}
		l'(x) & = d \exp{-\frac{1}{2\sigma_{\scalebox{0.65}{$\kern-3pt\bm{y}_{\mathcal{D}}$}}^2} x^2} \left(1 - x^2 \frac{1}{\sigma_{\scalebox{0.65}{$\kern-3pt\bm{y}_{\mathcal{D}}$}}^2}\right), \\
		l''(x) & = - d \exp{-\frac{1}{2\sigma_{\scalebox{0.65}{$\kern-3pt\bm{y}_{\mathcal{D}}$}}^2} x^2} \frac{1}{\sigma_{\scalebox{0.65}{$\kern-3pt\bm{y}_{\mathcal{D}}$}}^2} x \left(\left(1 - x^2 \frac{1}{\sigma_{\scalebox{0.65}{$\kern-3pt\bm{y}_{\mathcal{D}}$}}^2}\right) + 2\right) = \\
		& = - d \exp{-\frac{1}{2\sigma_{\scalebox{0.65}{$\kern-3pt\bm{y}_{\mathcal{D}}$}}^2} x^2} \frac{1}{\sigma_{\scalebox{0.65}{$\kern-3pt\bm{y}_{\mathcal{D}}$}}^2} x \left(3 - \frac{x^2}{\sigma_{\scalebox{0.65}{$\kern-3pt\bm{y}_{\mathcal{D}}$}}^2}\right),
	\end{align*}

 \label{cor:convposterior}
	Given $f_{\bm{\theta}}$ BNN, with architecture $\bm{\alpha} = (\bm{n}, \bm{\varphi})$, $\bm{\varphi}$ collection of Lipschitz activation functions, prior distribution on $\bm{\theta}$ as in \cref{eq:nealprior}, $G$ Gaussian process as in \cref{eq:nngp}, $\bm{x}$, $\bm{y}_{\mathcal{D}}$ as in \Cref{subsec:postbnn}, and a Gaussian likelihood function $\mathcal{L} \sim \normal{\bm{z}}{\sigma_{\scalebox{0.65}{$\kern-3pt\bm{y}_{\mathcal{D}}$}}^2 \bm{I}_{n_L \times k}}$, exists a constant
	\begin{equation*}
		c\left(\mathcal{D}, \bm{\varphi}, \bm{\sigma}, \sigma_{\scalebox{0.65}{$\kern-3pt\bm{y}_{\mathcal{D}}$}}^2, n_L\right) > 0, \text{ independent of } \left(n_l\right)_{l = 1}^{L - 1},
	\end{equation*}
	such that,
	\begin{equation*}
		\wass[1]{f_{\bm{\theta}}(\bm{x}) \, | \, \mathcal{D}}{G(\bm{x}) \, | \, \mathcal{D}} \leq c \frac{1}{\sqrt{n_{min}}},
	\end{equation*}
	for all $\displaystyle n_{min} \coloneqq \min_{l = 1, \dots, L - 1} n_l$ sufficiently large.

Let $\widetilde{\mu}$ the law of the induced prior distribution of a BNN, $\widetilde{\mu} \sim f_{\bm{\theta}}(\bm{x})$, and $\mu$ be the law of the associated NNGP, $\mu \sim G(\bm{x})$, probability measures on $\left(\mathbb{R}^{n_L \times k}, \norm{\cdot}\right)$. \\
Let $g \coloneqq \mathcal{L}: \mathbb{R}^{n_L \times k} \to \mathbb{R}$, bounded Lipschitz map.
The posterior distributions $\mathbb{P}_{f_{\bm{\theta}}(\bm{x}) | \mathcal{D}}$ and $\mathbb{P}_{G(\bm{x}) | \mathcal{D}}$ are, by construction, respectively equal to $\widetilde{\mu}_g$ and $\mu_g$ as they are defined in \Cref{lem:nnposterior}, therefore, by a direct application with $p = 2$, we get the following rewriting of \cref{eq:wassposterior}:
\begin{equation} \label{eq:wasspostcor}


	\begin{aligned}
		& \wass[1]{f_{\bm{\theta}}(\bm{x}) \, | \, \mathcal{D}}{G(\bm{x}) \, | \, \mathcal{D}} \leq \frac{1}{p^{(1)}} \left(\lipschitz{\mathcal{L}} p^{(3)} + \left(1 + \frac{p^{(4)} \lipschitz{\mathcal{L}}}{p^{(2)}}\right) \norm{\mathcal{L}}_{\infty}\right) \wass[2]{f_{\bm{\theta}}(\bm{x})}{G(\bm{x})},
	\end{aligned}
\end{equation}
where $\lipschitz{\mathcal{L}}, \norm{\mathcal{L}}_{\infty}$ are positive constants depending on $k, \sigma_{\scalebox{0.65}{$\kern-3pt\bm{y}_{\mathcal{D}}$}}^2, n_L$, as showed in \Cref{prop:likelihood}, and
\begin{equation*}
	\begin{gathered}
		p^{(1)} = \mean[\bm{z} \sim G(\bm{x})]{\mathcal{L}(\bm{z}; \bm{y}_{\mathcal{D}})}, \ p^{(2)} = \mean[\bm{z} \sim f_{\bm{\theta}}(\bm{x})]{\mathcal{L}(\bm{z}; \bm{y}_{\mathcal{D}})}, \\
		p^{(3)} = \mean[\bm{z} \sim G(\bm{x})]{\norm{\bm{z}}_F^{2}}, \ p^{(4)} = \mean[\bm{z} \sim G(\bm{x})]{\norm{\bm{z}}_F}.
	\end{gathered}
\end{equation*}
It is immediate that $p^{(3)}$ and $p^{(4)}$ are finite indeed they are the second and the first moment of a multivariate centered Gaussian, $G(\bm{x}) \sim \normal{\bm{0}_{n_L \times k}}{\bm{I}_{n_L} \otimes \bm{K}(\bm{x})}$, respectively. Therefore, as we observed in \Cref{rem:gaussmoments}, it holds
\begin{align} \label{eq:p3-4}
(p^{(4)})^2 \leq p^{(3)} & = \trace{\bm{I}_{n_L} \otimes \bm{K}(\bm{x})} = n_L \trace{\bm{K}(\bm{x})} \leq n_L k \max_{i \in [k]} \bm{K}(\bm{x}_i, \bm{x}_i) \leq \nonumber \\
	& \leq n_L k \left(\sigma_{\bm{W}^{(L)}}^2 \max_{i \in [k]} \mean{\norm{\varphi_{L}\left(G^{(L - 1)}(\bm{x}_i)\right)}_2^2} / n_L + \sigma_{\bm{b}^{(L)}}^2\right).
\end{align} 
So both the terms can be bounded by expressions only dependent on $\bm{x}, \bm{\varphi}, \bm{\sigma}$ and $n_L$. \\
For the remaining terms we still exploit the normality of $G(\bm{x})$ (see \cref{eq:nngpx}). 
Due to the boundedness and positivity of $\mathcal{L}: \mathbb{R}^{d_{\mathrm{out} \times k}} \to (0, \norm{\mathcal{L}}_{\infty})$, it is clear that $p^{(1)} \in (0, \infty)$, indeed we are integrating $\mathcal{L}$ with respect to a strictly positive probability measure: $0 < p^{(1)}(\mathcal{D}, \bm{\varphi}, \bm{\sigma}, \sigma_{\scalebox{0.65}{$\kern-3pt\bm{y}_{\mathcal{D}}$}}^2, n_L) =$ $= \mean{\mathcal{L}(G(\bm{x}); \bm{y}_{\mathcal{D}})} \leq \norm{\mathcal{L}}_{\infty}$. \\
Moreover, it is possible to notice that considering $\bm{v} \sim G(\bm{x})$, $\bm{w} \sim f_{\bm{\theta}}(\bm{x})$,
\begin{align*}
	|p^{(1)} - p^{(2)}| & = \left|\mean{\mathcal{L}(\bm{v}; \bm{y}_{\mathcal{D}}) - \mathcal{L}(\bm{w}; \bm{y}_{\mathcal{D}})}\right| \leq \norm{\mathcal{L}(\bm{v}; \bm{y}_{\mathcal{D}}) - \mathcal{L}(\bm{w}; \bm{y}_{\mathcal{D}})}_{L^1} \leq \lipschitz{\mathcal{L}} \norm{\bm{v} - \bm{w}}_{L^1},
\end{align*}
and taking the infimum over the couplings $(\bm{v}, \bm{w})$ we get
\begin{align} \label{eq:p1-2}
	|p^{(1)} - p^{(2)}| \leq \lipschitz{\mathcal{L}} \wass[1]{G(\bm{x})}{f_{\bm{\theta}}(\bm{x})} \leq \lipschitz{\mathcal{L}} c_1 \frac{1}{\sqrt{n_{min}}},
\end{align}
where for the last inequality we used a compact version of the result in \Cref{thm:priornngp}. Recalling that $c_1$ and $\lipschitz{\mathcal{L}}$ depend only on $\bm{x}, \bm{\varphi}, \bm{\sigma}, \sigma_{\scalebox{0.65}{$\kern-3pt\bm{y}_{\mathcal{D}}$}}^2$ and $n_L$, \cref{eq:p1-2} implies that, for $n_{min}$ sufficiently large, $p^{(2)}$  is also strictly positive. \\
To conclude it is sufficient to note that \cref{eq:wasspostcor}, together with \Cref{thm:priornngp} and the observations made about $(p^{(i)})_{i = 1}^4$ lead to
\begin{align*}
	\wass[1]{f_{\bm{\theta}}(\bm{x}) \, | \, \mathcal{D}}{G(\bm{x}) \, | \, \mathcal{D}} & \leq c_2 \wass[2]{f_{\bm{\theta}}(\bm{x})}{G(\bm{x})} \leq c_2 c_3 \sqrt{n_L} \sum_{l = 1}^{L} \frac{1}{\sqrt{n_k}} \leq c \frac{1}{\sqrt{n_{min}}},
\end{align*}
where $c_2$ and $c_3$ depends on $\mathcal{D}, \bm{\varphi}, \bm{\sigma}, \sigma_{\scalebox{0.65}{$\kern-3pt\bm{y}_{\mathcal{D}}$}}^2, n_L$.

\begin{equation*}
		\begin{gathered}
			p^{(1)} = \mean[\bm{z} \sim G(\bm{x})]{\mathcal{L}(\bm{z}; \bm{y}_{\mathcal{D}})}, \ p^{(2)} = \mean[\bm{z} \sim f_{\bm{\theta}}(\bm{x})]{\mathcal{L}(\bm{z}; \bm{y}_{\mathcal{D}})}, \\
			p^{(3)} = \mean[\bm{z} \sim G(\bm{x})]{\norm{\bm{z}}_F^{2}}, \ p^{(4)} = \mean[\bm{z} \sim G(\bm{x})]{\norm{\bm{z}}_F}.
		\end{gathered}
	\end{equation*}

\begin{align} \label{eq:p3-4}
	(p^{(4)})^2 \leq p^{(3)} & = \trace{\bm{I}_{n_L} \otimes \bm{K}(\bm{x})} = n_L \trace{\bm{K}(\bm{x})} \leq n_L k \max_{i \in [k]} \bm{K}(\bm{x}_i, \bm{x}_i) \leq \nonumber \\
		& \leq n_L k \left(\sigma_{\bm{W}^{(L)}}^2 \max_{i \in [k]} \mean{\norm{\varphi_{L}\left(G^{(L - 1)}(\bm{x}_i)\right)}_2^2} / n_L + \sigma_{\bm{b}^{(L)}}^2\right).
	\end{align}

 \label{lem:priornngpsigma}


	Given $f_{\bm{\theta}}$, $G$ and $\bm{x}$ as in \Cref{thm:priornngp}, $p \geq 1$, and assuming $\sigma^2 \coloneqq \sigma_{\bm{W}^{(L)}}^2 =$ $= \sigma_{\bm{b}^{(L)}}^2 = \sigma_{\scalebox{0.65}{$\kern-3pt\bm{y}_{\mathcal{D}}$}}^2$, there exists a constant
	\begin{equation*}
		c\left(p, \bm{x}, \bm{\varphi}, (\bm{\sigma}_l)_{l = 1}^{L - 1}\right) > 0, \text{ independent of } \left(n_l\right)_{l = 1}^L, \sigma^2,
	\end{equation*}
	such that
	\begin{equation*}
		\wass[p]{f_{\bm{\theta}}(\bm{x}) \, | \, \sigma^2}{G(\bm{x}) \, | \, \sigma^2} \leq \sigma c \sqrt{n_L} \sum_{l = 1}^{L - 1} \frac{1}{\sqrt{n_l}},
	\end{equation*}



The proof is straightforward if we observe that, by construction (see \cref{eq:nn,eq:nngpx}) $f_{\bm{\theta}} = \sigma f_{\bm{\theta}'}$ and $G = \sigma  G'$, with 
\begin{equation} \label{eq:thetaprime}
	\bm{\theta}' \text{ such that } \bm{\sigma}' = \left(\left(\left(\sigma_{\bm{W}^{(l)}}^2, \sigma_{\bm{b}^{(l)}}^2\right)\right)_{l = 1}^{L - 1}, (1, 1)\right),
\end{equation}
and $G'$ built with weights and bias variances as in $\bm{\sigma}'$. \\
Indeed, applying \cref{eq:wasslinear} and \Cref{thm:priornngp} we get
\begin{equation*}
	\wass[p]{f_{\bm{\theta}}(\bm{x}) \, | \, \sigma^2}{G(\bm{x}) \, | \, \sigma^2} =\sigma \wass[p]{f_{\bm{\theta}}'(\bm{x})}{G'(\bm{x})} \leq \sigma c \sqrt{n_L} \sum_{l = 1}^{L - 1} \frac{1}{\sqrt{n_L}}, 
\end{equation*}
with $c$ independent of $\sigma^2$.

 \label{lem:boundexplikelihood}


	Given $f_{\bm{\theta}}$, $G$, $\bm{x}$, $\bm{y}_{\mathcal{D}}$ and $\mathcal{L}$ as in \Cref{cor:convposterior}, assuming $\sigma^2 \coloneqq \sigma_{\bm{W}^{(L)}}^2 = \sigma_{\bm{b}^{(L)}}^2 =$ $= \sigma_{\scalebox{0.65}{$\kern-3pt\bm{y}_{\mathcal{D}}$}}^2$, $\bm{K}'(\bm{x}) \in \operatorname{Sym}_+^{k}$ (rescaled NNGP kernel), and 
