\begin{equation*}


		\begin{aligned}
			c_1 \cdot \left(\sigma^2\right)^{- n_L k / 2} \exp{-\frac{\norm{\bm{y}_{\mathcal{D}}}_F^2}{\sigma^2}} \leq \ & \mean{\mathcal{L}(\bm{v}; \bm{y}_{\mathcal{D}})} \leq c_2 \cdot \left(\sigma^2\right)^{- n_L k / 2} \exp{-\frac{1}{2 \sigma^2} \frac{\varepsilon}{\varepsilon + 1} \norm{\bm{y}_{\mathcal{D}}}_F^2}, \\
			c_3 \exp{-\frac{\norm{\bm{y}_{\mathcal{D}}}_F^2}{\sigma^2}} \leq \ & \mean{\mathcal{L}(\bm{w}; \bm{y}_{\mathcal{D}})} \leq c_4 \cdot \left(\sigma^2\right)^{- n_L k / 2},
