We separately discuss the four bounds.

\textbf{Bounds related to $G(\bm{x})$.}	It is possible to rewrite $\mean{\mathcal{L}(\bm{v}; \bm{y}_{\mathcal{D}})}$ as follows:
\begin{align} \label{eq:nngpexplikelihood}
	\mean{\mathcal{L}(\bm{v}; \bm{y}_{\mathcal{D}})} & \propto \mean{\left(\sigma^2\right)^{- n_L k / 2} \exp{-\frac{1}{2\sigma^2} \norm{\bm{y}_{\mathcal{D}} - \bm{v}}_F^2}} = \nonumber \\
	& = \left(\sigma^2\right)^{- n_L k / 2} \int_{\mathbb{R}^{n_L \times k}} \exp{-\frac{1}{2\sigma^2} \norm{\bm{y}_{\mathcal{D}} - \bm{v}}_F^2} d \mathbb{P}_{G(\bm{x}) | \sigma^2}(\bm{v}).
\end{align}
Starting with the density of the Gaussian variable $G(\bm{x})$,
\begin{equation*}
	\begin{aligned}	
		p_{G(\bm{x})}(\bm{z}) & = \frac{1}{\left((2\pi)^{n_L k} \det{\bm{K}(\bm{x}) \otimes_K \bm{I}_{n_L}}\right)^{1/2}} \cdot \\
		& \kern14.65pt \cdot \exp{-\frac{1}{2} \flatten{\bm{z}}^T \left(\bm{K}(\bm{x}) \otimes_K \bm{I}_{n_L} \right)^{-1} \flatten{\bm{z}}},
	\end{aligned}
\end{equation*}
and recalling that, $\forall\,\,\,\, \bm{A} \in \mathbb{R}^{n \times n}, \bm{B} \in \mathbb{R}^{k \times k}$, then $(\bm{A} \otimes_K \bm{B})^{-1} = \bm{A}^{-1} \otimes_K \bm{B}^{-1}$, $\det{\bm{A} \otimes_K \bm{B}} =$ $= \det{\bm{A}}^k \det{\bm{B}}^n$, and $\bm{K}(\bm{x}) = \sigma^2 \bm{K}'(\bm{x})$, with $\bm{K}'(\bm{x})$ as in \cref{eq:rescaledkernel}, it is easy to see that 
\begin{equation} \label{eq:densitynngp}
	\begin{aligned}	
		p_{G(\bm{x}) | \sigma^2}(\bm{v}) = \frac{1}{(2 \pi \sigma^2)^{n_L k / 2}} \frac{1}{\det{\bm{K}'(\bm{x})}^{n_L / 2}} \exp{-\frac{1}{2 \sigma^2} \sum_{i, j \in [k] \times [k]} \left(\bm{K}'(\bm{x})^{-1}\right)_{i, j} \bm{v}_i^T \bm{v}_j}.
	\end{aligned}
\end{equation}

\textbf{Lower bound.} Substituting \cref{eq:densitynngp} in \cref{eq:nngpexplikelihood} we get
\begin{align} 
	& \begin{aligned} \label{eq:nngpexplikprop}
		\mean{\mathcal{L}(\bm{v}; \bm{y}_{\mathcal{D}})} & \propto \left(\sigma^2\right)^{- n_L k} \int_{\mathbb{R}^{n_L \times k}} \exp{-\frac{1}{2\sigma^2} \norm{\bm{y}_{\mathcal{D}} - \bm{v}}_F^2} \cdot \\
		& \kern14.65pt \cdot \exp{-\frac{1}{2\sigma^2} \sum_{i, j \in [k] \times [k]} \left(\bm{K}'(\bm{x})^{-1}\right)_{i, j} \bm{v}_i^T \bm{v}_j} d\bm{v} \geq 
	\end{aligned} \\
	& \kern49.75pt \begin{aligned} \label{eq:nngpexplikgeq}
		& \geq \left(\sigma^2\right)^{- n_L k} \exp{-\frac{1}{\sigma^2} \norm{\bm{y}_{\mathcal{D}}}_F^2} \left(\sigma^2\right)^{n_L k /2} \cdot \\
		& \kern14.65pt \cdot \int_{\mathbb{R}^{n_L \times k}} \exp{-\frac{1}{2} \left(\sum_{i, j \in [k] \times [k]} \left(\bm{K}'(\bm{x})^{-1} + 2 \cdot \bm{I}_k\right)_{i, j} \bm{u}_i^T \bm{u}_j\right)} d\bm{u},
	\end{aligned}
\end{align}
where the inequality follows applying $\norm{\bm{y}_{\mathcal{D}} - \bm{v}}_F^2 \leq 2(\norm{\bm{y}_{\mathcal{D}}}_F^2 + \norm{\bm{v}}_F^2)$ (see \cref{eq:ineqnormsqleq}) and performing the change of variable $\bm{u} \coloneqq \bm{v} / (\sigma^2)^{1/2}$. 
The conclusion for the lower bound follows easily observing that $\bm{K}'(\bm{x})$ is positive definite, so it holds 
\begin{equation*}
	(\bm{K}'(\bm{x})^{-1} + 2 \cdot \bm{I}_k) \otimes_K \bm{I}_{n_L} \in \operatorname{Sym}_+^{n_L k}, 
\end{equation*}
and therefore given $\bm{u}_{\mathrm{f}} = \flatten{\bm{u}}$ the integral in \cref{eq:nngpexplikgeq} is equal to a constant depending on $\bm{x}, \bm{\varphi}, \left(\bm{\sigma}_l\right)_{l = 1}^{L - 1}, n_L$: 
\begin{equation} \label{eq:boundinfthetaprime}
	\begin{aligned}
		& \int_{\mathbb{R}^{n_L \times k}} \exp{-\frac{1}{2} (\bm{u}_{\mathrm{f}}^T \left((\bm{K}'(\bm{x})^{-1} + 2 \cdot \bm{I}_k) \otimes_K \bm{I}_{n_L}\right) \bm{u}_{\mathrm{f}})} d\bm{u}_{\mathrm{f}} = \\
		& \kern20pt = \left((2\pi)^{k} \det{\bm{K}'(\bm{x})^{-1} + 2 \cdot \bm{I}_k}\right)^{n_L / 2}.
	\end{aligned}
\end{equation}   

\textbf{Upper bound.} For the upper bound the procedure is similar.
Starting from the result in \cref{eq:nngpexplikprop}, applying the inequality $\norm{\bm{y}_{\mathcal{D}} - \bm{v}}_F^2 \geq \frac{\varepsilon}{1 + \varepsilon} \norm{\bm{y}_{\mathcal{D}}}_F^2 - \varepsilon \norm{\bm{v}}_F^2$, for a fixed $\varepsilon > 0$ (see \cref{eq:ineqnormsqgeqeps}) and performing again the change of variable $\bm{u} \coloneqq \bm{v} / (\sigma^2)^{1/2}$ we get
\begin{align*}
	\mean{\mathcal{L}(\bm{v}; \bm{y}_{\mathcal{D}})} & \leq c \cdot \left(\sigma^2\right)^{- n_L k} \exp{-\frac{1}{2 \sigma^2} \frac{\varepsilon}{\varepsilon + 1} \norm{\bm{y}_{\mathcal{D}}}_F^2} \left(\sigma^2\right)^{n_L k /2} \cdot \\
	& \kern14.65pt \cdot \int_{\mathbb{R}^{n_L \times k}} \exp{-\frac{1}{2} \sum_{i, j \in [k] \times [k]} \left(\bm{K}'(\bm{x})^{-1} - \varepsilon \bm{I}_k\right)_{i, j} \bm{v}_i^T \bm{v}_j} d\bm{v}.
\end{align*}
Now, in order to have a convergent integral it is sufficient to impose the matrix $\bm{K}'(\bm{x})^{-1} - \varepsilon \bm{I}_k$ to be positive definite. Indeed, in that case, we could conclude as before. 
However, this condition is obviously verified 
\begin{equation*}
	\forall\,\,\,\, \varepsilon < \min\left\{\lambda \, | \, \lambda \in \operatorname{Sp}\left(\bm{K}'(\bm{x})^{-1}\right)\right\} = \max\left\{\lambda \, | \, \lambda \in \operatorname{Sp}\left(\bm{K}'(\bm{x})\right)\right\}^{-1} = 1/\norm{\bm{K}'(\bm{x})}_{\mathrm{op}},
\end{equation*}
indeed for such $\varepsilon$ one has that 
\begin{equation*}
	\operatorname{Sp}\left(\bm{K}'(\bm{x})^{-1} - \varepsilon \bm{I}_k\right) = \operatorname{Sp}\left(\bm{K}'(\bm{x})^{-1}\right) - \varepsilon \subset \mathbb{R}^+.
\end{equation*}

\textbf{Bounds related to $f_{\bm{\theta}}(\bm{x})$.} As for the Gaussian process we can write 
\begin{equation} \label{eq:nnexplikelihood}
	\mean{\mathcal{L}(\bm{w}; \bm{y}_{\mathcal{D}})} \propto \left(\sigma^2\right)^{- n_L k / 2} \int_{\mathbb{R}^{n_L \times k}} \exp{-\frac{1}{2\sigma^2} \norm{\bm{y}_{\mathcal{D}} - \bm{w}}_F^2} d \mathbb{P}_{f_{\bm{\theta}}(\bm{x}) | \sigma^2}(\bm{w}).
\end{equation}
We also recall the definitions of $f_{\bm{\theta}'} = (\sigma^2)^{-1/2} f_{\bm{\theta}}$ and $G' = (\sigma^2)^{-1/2} G$, respectively the rescaled BNN and NNGP, random processes independent on $\sigma^2$, as in \cref{eq:thetaprime}.

\textbf{Lower bound.} Applying the same inequality and the same change of variable used in the lower bound related to $G(\bm{x})$ we get 
\begin{align} \label{eq:nnexplikgeq}
	\mean{\mathcal{L}(\bm{w}; \bm{y}_{\mathcal{D}})} & \geq c \exp{-\frac{1}{\sigma^2} \norm{\bm{y}_{\mathcal{D}}}_F^2} \int_{\mathbb{R}^{n_L \times k}} \exp{-\norm{\bm{u}}_F^2} d \mathbb{P}_{f_{\bm{\theta}}'(\bm{x})}(\bm{u}) \nonumber = \\
	& = c \exp{-\frac{1}{\sigma^2} \norm{\bm{y}_{\mathcal{D}}}_F^2} \mean[\bm{u} \sim f_{\bm{\theta}}'(\bm{x})]{e^{-\norm{\bm{u}}_F^2}}.
\end{align}
Now, we can exploit the fact that we know how to integrate $e^{-\norm{\bm{\cdot}}_F^2}$ with respect to the measure $\mathbb{P}_{G'(\bm{x})}$ (we already computed this integral up to a constant depending on the usual parameters, in \cref{eq:boundinfthetaprime}) to obtain analogous results for the mean value in \cref{eq:nnexplikgeq}. 
As in \cref{eq:p1-2}, exploiting \Cref{thm:priornngp}, and observing that
\begin{align*}
	\lipschitz{e^{-\norm{\bm{\cdot}}_F^2}} & = \max_{\bm{u} \in \mathbb{R}^{n_L \times k}} \norm{\frac{\partial}{\partial \bm{u}} e^{-\norm{\bm{u}}_F^2}}_F = \max_{\bm{u} \in \mathbb{R}^{n_L \times k}} \norm{-2 \bm{u} e^{-\norm{\bm{u}}_F^2}}_F = \sqrt{\frac{2}{e}},
\end{align*}
it is possible to write the following upper bound to the difference of the mean values of $e^{-\norm{\bm{\cdot}}_F^2}$ with respect to the laws of $G'(\bm{x})$ and $f_{\bm{\theta}'}(\bm{x})$:
\begin{equation} \label{eq:boundmeanexpscaled}
	\begin{aligned}
		& \left|\mean[\bm{u} \sim G'(\bm{x})]{e^{-\norm{\bm{u}}_F^2}} - \mean[\bm{u} \sim f_{\bm{\theta}}'(\bm{x})]{e^{-\norm{\bm{u}}_F^2}}\right| \leq \lipschitz{e^{-\norm{\bm{\cdot}}_F^2}} \wass[1]{G'(\bm{x})}{f_{\bm{\theta}'}(\bm{x})} \leq \frac{c}{\sqrt{n_{min}}}.
	\end{aligned}
\end{equation}
Therefore, assuming 
\begin{equation*}
	\sqrt{n_{min}} \geq 2c / \mean[\bm{u} \sim G'(\bm{x})]{e^{-\norm{\bm{u}}_F^2}},
\end{equation*}
we get 
\begin{equation*}
	\mean[\bm{u} \sim f_{\bm{\theta}}'(\bm{x})]{e^{-\norm{\bm{u}}_F^2}} \geq \mean[\bm{u} \sim G'(\bm{x})]{e^{-\norm{\bm{u}}_F^2}} / 2,
\end{equation*}
and therefore
\begin{equation*}
	\mean{\mathcal{L}(\bm{w}; \bm{y}_{\mathcal{D}})} \geq c \exp{-\frac{1}{\sigma^2} \norm{\bm{y}_{\mathcal{D}}}_F^2}.
\end{equation*}

